using System;
using System.IO;
using System.IO.Pipes;
using System.Linq;
using System.Collections.Generic;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace QiDesk {
public sealed class McpBridge : IDisposable {
    readonly Controller controller;readonly string pipeName;volatile bool stopped;NamedPipeServerStream current;readonly object gate=new object();
    public static string PipeName {get{return "QiDesk-MCP-"+WindowsIdentity.GetCurrent().User.Value;}}
    public McpBridge(Controller owner,string name){controller=owner;pipeName=name;var thread=new Thread(Listen){IsBackground=true,Name="QiDesk local MCP"};thread.Start();}
    static string Line(StreamReader reader){var s=new StringBuilder();int c;while((c=reader.Read())>=0){if(c=='\n')return s.ToString();if(c!='\r')s.Append((char)c);if(s.Length>65536)throw new InvalidDataException("Request too large");}return s.Length==0?null:s.ToString();}
    void Listen(){while(!stopped){try{var security=new PipeSecurity();security.SetAccessRuleProtection(true,false);security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(pipeName,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,65536,65536,security)){lock(gate){if(stopped)return;current=pipe;}pipe.WaitForConnection();using(var watchdog=new Timer(delegate{try{pipe.Dispose();}catch{}},null,15000,Timeout.Infinite))using(var reader=new StreamReader(pipe,new UTF8Encoding(false),false,4096,true))using(var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true}){string line=Line(reader);if(line==null)continue;var request=Store.Json.Deserialize<Dictionary<string,object>>(line);var completion=new TaskCompletionSource<object>();controller.Manager.Dispatcher.BeginInvoke(new Action(async delegate{try{if(stopped||!controller.Store.Data.McpEnabled)throw new Exception("MCP connection is disabled.");completion.SetResult(await ExecuteAsync(controller,request));}catch(Exception ex){completion.SetResult(new {error=ex.Message});}}));if(completion.Task.Wait(10000))writer.WriteLine(Store.Json.Serialize(completion.Task.Result));else writer.WriteLine("{\"error\":\"Application is busy.\"}");}}}catch(Exception ex){if(stopped)return;try{File.AppendAllText(Path.Combine(controller.Store.Root,"errors.log"),DateTime.Now+" MCP listener: "+ex.Message+Environment.NewLine);}catch{}Thread.Sleep(500);}finally{lock(gate){current=null;}}}}
    public void Dispose(){stopped=true;lock(gate){if(current!=null)try{current.Dispose();}catch{}}}
    static string Text(Dictionary<string,object> args,string key){object x;return args.TryGetValue(key,out x)?Convert.ToString(x):"";}
    static Group Target(Store store,string id){var g=store.Data.Groups.FirstOrDefault(x=>x.Id==id);if(g==null)throw new Exception("Unknown groupId.");return g;}
    static List<IgnoreRule> Rules(Store store,string id){return String.IsNullOrEmpty(id)?store.Data.IgnoreRules:Target(store,id).IgnoreRules;}
    static string Workspace(State state,string index){int n;if(!Int32.TryParse(index,out n)||n<0||n>=state.WorkFolders.Count)throw new Exception("Unknown workspaceId.");return state.WorkFolders[n];}
    public static async Task<object> ExecuteAsync(Controller controller,Dictionary<string,object> request){
        if(Text(request,"name")!="qidesk_search_files")return Execute(controller,request);
        ValidateCall(request);var args=(Dictionary<string,object>)request["arguments"];string scope=Text(args,"scope");if(scope.Length>0&&scope!="project"&&scope!="all")throw new Exception("scope must be project or all.");
        string workspaceId=Text(args,"workspaceId");if(scope=="all"&&workspaceId.Length>0)throw new Exception("workspaceId cannot be combined with scope all.");
        string root=scope=="all"?null:workspaceId.Length>0?Workspace(controller.Store.Data,workspaceId):WorkspaceSelection.Current(controller.Store.Data);
        if(root!=null&&!WorkspaceSelection.Available(root))throw new Exception("Connect or select an available workspace first.");
        State snapshot=Store.Json.Deserialize<State>(Store.Json.Serialize(controller.Store.Data));string directory=controller.Store.Root,query=Text(args,"query");
        return await Task.Run<object>(()=>FileSearch.Query(new StoreView(directory,snapshot).Store,query,String.IsNullOrWhiteSpace(query),60,root));
    }
    static void SafeFile(string path,string root){if(!Path.IsPathRooted(path)||!WorkDetection.Under(path,root)||!Store.Exists(path))throw new Exception("File must exist inside a registered workspace.");string current=Path.GetFullPath(path),boundary=IgnoreRule.Canonical(root);while(current.Length>=boundary.Length){if((File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new Exception("Directory links are outside the permitted scope.");if(String.Equals(IgnoreRule.Canonical(current),boundary,StringComparison.OrdinalIgnoreCase))return;var parent=Directory.GetParent(current);if(parent==null)break;current=parent.FullName;}throw new Exception("Workspace boundary mismatch.");}
    public static object Execute(Controller controller,Dictionary<string,object> request){
        string requestedTool=Text(request,"name");var definition=Tools().Concat(new object[]{Definition("qidesk_sync_roots","Internal client roots registration.",false,new[]{"paths","source"},"paths","source")}).Cast<Dictionary<string,object>>().FirstOrDefault(t=>Convert.ToString(t["name"])==requestedTool);if(definition==null)throw new Exception("Unknown tool.");ValidateArguments(definition,request);
        var store=controller.Store;string name=Text(request,"name");object raw;var args=request.TryGetValue("arguments",out raw)?raw as Dictionary<string,object>:null;args=args??new Dictionary<string,object>();string id=Text(args,"groupId");
        if(name=="qidesk_get_current_workspace")return WorkspaceSelection.Describe(store.Data);
        if(name=="qidesk_show_workspace"&&String.IsNullOrEmpty(Text(args,"workspaceId"))){if(controller.Manager==null)throw new Exception("Application window unavailable.");controller.Manager.ShowWorkspaceSearch();return new {shown=true,workspace=WorkspaceSelection.Describe(store.Data)};}
        if(name=="qidesk_list_groups")return store.Data.Groups.Select(g=>new {id=g.Id,name=g.Name,page=g.Page+1,mapped=!String.IsNullOrEmpty(g.Folder),view=g.ViewMode,visibleItems=store.Items(g,"").Count()}).ToArray();
        if(name=="qidesk_list_items"){var g=Target(store,id);return store.Items(g,"").Take(300).Select(p=>new {name=Path.GetFileName(p),type=FilePresentation.Type(p),size=FilePresentation.Size(p)}).ToArray();}
        if(name=="qidesk_list_workspaces")return store.Data.WorkFolders.Select((p,i)=>new {workspaceId=i.ToString(),name=FilePresentation.FolderName(p),path=p,current=String.Equals(p,WorkspaceSelection.Current(store.Data),StringComparison.OrdinalIgnoreCase),available=Directory.Exists(p),markers=WorkDetection.Markers(p),source=store.Data.WorkSources.ContainsKey(p)?store.Data.WorkSources[p]:"手动",ignoreFiles=store.Data.IgnoreFiles.Count(s=>s.Root==p)}).ToArray();
        if(name=="qidesk_list_widgets")return store.Data.Widgets.Select(w=>new {id=w.Id,name=w.Name,pluginId=w.PluginId,page=w.Page+1}).ToArray();
        if(name=="qidesk_list_ignores")return Rules(store,id).Select(r=>new {id=r.Id,pattern=r.Kind=="路径"?Path.GetFileName(r.Pattern):r.Pattern,kind=r.Kind,enabled=r.Enabled}).ToArray();
        if(name=="qidesk_detect_generated")return WorkDetection.Scan(store.Data).Select(x=>new {name=x.Name,workspace=x.Workspace,reason=x.Reason,ignored=store.Ignored(x.Path,null)}).ToArray();
        if(name=="qidesk_get_settings")return AiSettings.Get(store);if(name=="qidesk_search_files")throw new InvalidOperationException("File searches must use ExecuteAsync.");string previous=Store.Json.Serialize(store.Data);store.Checkpoint();bool rebuild=false;object result;
        try{
            if(name=="qidesk_set_current_workspace"||name=="qidesk_show_workspace"){WorkspaceSelection.Select(store.Data,Workspace(store.Data,Text(args,"workspaceId")));result=WorkspaceSelection.Describe(store.Data);if(name=="qidesk_show_workspace"){if(controller.Manager==null)throw new Exception("Application window unavailable.");controller.Manager.ShowWorkspaceSearch();}}
            else if(AiSettings.Apply(controller,name,args,out result)){rebuild=true;}else if(name=="qidesk_connect_workspace"){string path=Text(args,"path");bool added=WorkspaceConnections.Connect(store.Data,path,Text(args,"source"),false);result=new {connected=true,added=added,workspaceId=store.Data.WorkFolders.FindIndex(p=>String.Equals(IgnoreRule.Canonical(p),IgnoreRule.Canonical(path),StringComparison.OrdinalIgnoreCase)).ToString()};}
            else if(name=="qidesk_sync_roots"){var paths=((System.Collections.IEnumerable)args["paths"]).Cast<object>().Select(Convert.ToString).Distinct(StringComparer.OrdinalIgnoreCase).Take(30).ToArray();int added=0;string first="";foreach(string path in paths){if(!WorkspaceConnections.SafeDirectory(path))continue;if(WorkspaceConnections.Connect(store.Data,path,Text(args,"source"),true))added++;if(first.Length==0&&store.Data.AutoDetectWorkspaces&&!store.Data.IgnoredWorkFolders.Contains(IgnoreRule.Canonical(path),StringComparer.OrdinalIgnoreCase))first=IgnoreRule.Canonical(path);}if(first.Length>0)WorkspaceSelection.Select(store.Data,first);result=new {detected=paths.Length,added=added,automatic=store.Data.AutoDetectWorkspaces};}
            else if(name=="qidesk_import_ignore_file"){string root=Workspace(store.Data,Text(args,"workspaceId")),file=Text(args,"fileName");if(!IgnoreFiles.Names.Contains(file)&&file!=".git/info/exclude")throw new Exception("Only known project ignore files may be imported.");string path=Path.Combine(root,file.Replace('/',Path.DirectorySeparatorChar));SafeFile(path,root);if(!String.IsNullOrEmpty(id))Target(store,id);var set=IgnoreFiles.Read(path,id,root,false);IgnoreFiles.Import(store.Data,set);result=new {imported=set.Lines.Count,ignoreFileId=set.Id};}
            else if(name=="qidesk_add_widget"){var widget=WidgetPlugins.Create(store.Data,Text(args,"pluginId"),Shell.WorkingAreas(controller.Manager));rebuild=true;result=new {widgetId=widget.Id};}
            else if(name=="qidesk_add_ignore"){string pattern=Text(args,"pattern");var rules=Rules(store,id);if(rules.Count>=500)throw new Exception("Rule limit reached.");var rule=new IgnoreRule(){Pattern=pattern};IgnoreRule.Validate(new List<IgnoreRule>{rule});rules.Add(rule);result=new {ruleId=rule.Id,scope=String.IsNullOrEmpty(id)?"global":id};}
            else if(name=="qidesk_remove_ignore"){var rules=Rules(store,id);string ruleId=Text(args,"ruleId");var rule=rules.FirstOrDefault(r=>r.Id==ruleId);if(rule==null)throw new Exception("Unknown ruleId.");rules.Remove(rule);result=new {removed=true};}
            else if(name=="qidesk_register_generated"){string root=Workspace(store.Data,Text(args,"workspaceId"));object pathsValue;if(!args.TryGetValue("paths",out pathsValue))throw new Exception("paths is required.");var paths=pathsValue as System.Collections.IEnumerable;if(paths==null||pathsValue is string)throw new Exception("paths must be an array.");var files=paths.Cast<object>().Select(Convert.ToString).Take(101).ToArray();if(files.Length==0||files.Length>100)throw new Exception("Register 1 to 100 files at a time.");var rules=Rules(store,id);foreach(string p in files)SafeFile(p,root);if(rules.Count+files.Length>500)throw new Exception("Rule limit reached.");int count=0;foreach(string p in files){string full=Path.GetFullPath(p);if(rules.Any(r=>r.Kind=="路径"&&String.Equals(IgnoreRule.Canonical(r.Pattern),IgnoreRule.Canonical(full),StringComparison.OrdinalIgnoreCase)))continue;rules.Add(new IgnoreRule(){Kind="路径",Pattern=full,IncludeChildren=Directory.Exists(full)});count++;}result=new {registered=count};}
            else if(name=="qidesk_create_portal"){string root=Workspace(store.Data,Text(args,"workspaceId"));if(!Directory.Exists(root))throw new Exception("Workspace is unavailable.");SafeFile(root,root);if(store.Data.Groups.Any(g=>String.Equals(IgnoreRule.Canonical(g.Folder),IgnoreRule.Canonical(root),StringComparison.OrdinalIgnoreCase)))throw new Exception("This workspace already has a portal.");string title=Text(args,"name").Trim();if(title.Length>80)throw new Exception("name must be at most 80 characters.");var createdGroup=new Group(){Name=title.Length==0?FilePresentation.FolderName(root):title,Folder=root,Page=store.Data.Page,X=80,Y=80,Width=380,Height=320};store.Data.Groups.Add(createdGroup);rebuild=true;result=new {groupId=createdGroup.Id};}
            else throw new Exception("Unknown tool.");
            store.Save();if(rebuild)controller.Rebuild();controller.UpdateDesktopIntegration();controller.Refresh();return result;
        }catch{store.Data=Store.Json.Deserialize<State>(previous);try{store.Save();controller.Rebuild();controller.Refresh();}catch{}throw;}
    }
    public static string Configuration(){string script=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","code","start-mcp.ps1"));if(!File.Exists(script))script=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","start-mcp.ps1"));return Store.Json.Serialize(new {mcpServers=new Dictionary<string,object>{{"qidesk",new {command="powershell.exe",args=new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",script}}}}});}
    public static int Serve(string pipeName,string workspace=""){return McpSession.Serve(pipeName,workspace);}
    public static void ValidateCall(Dictionary<string,object> call){string name=Text(call,"name");var definition=Tools().Cast<Dictionary<string,object>>().FirstOrDefault(t=>Convert.ToString(t["name"])==name);if(definition==null)throw new Exception("Unknown tool.");ValidateArguments(definition,call);}
    static void ValidateArguments(Dictionary<string,object> tool,Dictionary<string,object> call){object raw;var args=call.TryGetValue("arguments",out raw)?raw as Dictionary<string,object>:new Dictionary<string,object>();if(args==null)throw new Exception("arguments must be an object.");var schema=(Dictionary<string,object>)tool["inputSchema"];var properties=(Dictionary<string,object>)schema["properties"];foreach(string key in args.Keys){object def;if(!properties.TryGetValue(key,out def))throw new Exception("Unexpected argument: "+key);string type=Convert.ToString(((Dictionary<string,object>)def)["type"]);if(type=="string"&&(!(args[key] is string)||((string)args[key]).Length>1024))throw new Exception("Invalid argument: "+key);if(type=="object"){var values=args[key] as Dictionary<string,object>;if(values==null||values.Count==0)throw new Exception("Invalid settings object.");var allowed=(Dictionary<string,object>)((Dictionary<string,object>)def)["properties"];foreach(var pair in values){object member;if(!allowed.TryGetValue(pair.Key,out member))throw new Exception("Unexpected setting: "+pair.Key);string memberType=Convert.ToString(((Dictionary<string,object>)member)["type"]);if(memberType=="boolean"&&!(pair.Value is bool)||memberType=="string"&&(!(pair.Value is string)||((string)pair.Value).Length>2000)||((memberType=="integer"||memberType=="number")&&(pair.Value==null||pair.Value is bool||pair.Value is string)))throw new Exception("Invalid setting value: "+pair.Key);}}if(type=="array"){var array=args[key] as System.Collections.IEnumerable;if(array==null||args[key] is string||array.Cast<object>().Any(x=>!(x is string)||((string)x).Length>1024))throw new Exception("Invalid array: "+key);}}foreach(string key in (string[])schema["required"])if(!args.ContainsKey(key))throw new Exception("Missing argument: "+key);}
    static Dictionary<string,object> Definition(string name,string description,bool readOnly,string[] required,params string[] keys){var props=new Dictionary<string,object>();foreach(string key in keys)props[key]=key=="paths"?(object)new Dictionary<string,object>{{"type","array"},{"items",new {type="string"}},{"minItems",1},{"maxItems",100}}:new Dictionary<string,object>{{"type","string"},{"maxLength",1024}};return new Dictionary<string,object>{{"name",name},{"description",description},{"inputSchema",new Dictionary<string,object>{{"type","object"},{"properties",props},{"required",required},{"additionalProperties",false}}},{"annotations",new {readOnlyHint=readOnly,destructiveHint=false,openWorldHint=false}}};}
    public static object[] Tools(){return new object[]{
        Definition("qidesk_get_current_workspace","Get the current connected project used by Alt+Space. Does not infer the foreground editor.",true,new string[0]),
        Definition("qidesk_set_current_workspace","Select an existing workspace as the current project for Alt+Space.",false,new[]{"workspaceId"},"workspaceId"),
        Definition("qidesk_show_workspace","Show the floating project file search panel. Optionally select a connected workspace first.",false,new string[0],"workspaceId"),
        Definition("qidesk_search_files","Search current project files using Everything or bounded local fallback. Optional scope all searches the Everything index or configured local folders. Returns at most 60 results with paths; respects display ignores.",true,new[]{"query"},"query","workspaceId","scope"),
        Definition("qidesk_list_groups","List desktop groups without physical paths.",true,new string[0]),
        Definition("qidesk_list_items","List visible files in a group.",true,new[]{"groupId"},"groupId"),
        Definition("qidesk_list_workspaces","List user-selected AI workspace paths. Only these directories may be used for generated-file registration.",true,new string[0]),
        Definition("qidesk_list_ignores","List global or group ignore rules. Omitting groupId uses global scope.",true,new string[0],"groupId"),
        Definition("qidesk_detect_generated","Find candidates by file-name hints in registered workspaces; does not prove AI provenance.",true,new string[0]),
        Definition("qidesk_add_ignore","Add a display-only filename wildcard ignore rule, global or within one group.",false,new[]{"pattern"},"pattern","groupId"),
        Definition("qidesk_remove_ignore","Remove an ignore rule to restore visibility.",false,new[]{"ruleId"},"ruleId","groupId"),
        Definition("qidesk_register_generated","Register existing generated files inside a selected workspace for display-only ignore. Does not write or delete files.",false,new[]{"workspaceId","paths"},"workspaceId","paths","groupId"),
        Definition("qidesk_create_portal","Create a desktop portal pointing to an existing registered workspace; keeps its files in place.",false,new[]{"workspaceId"},"workspaceId","name"),
        Definition("qidesk_connect_workspace","Connect the user current project folder so ignore files are detected automatically. Use when client roots are unavailable.",false,new[]{"path"},"path","source"),
        Definition("qidesk_import_ignore_file","Import a known ignore file inside a connected project, globally or for one group.",false,new[]{"workspaceId","fileName"},"workspaceId","fileName","groupId"),
        Definition("qidesk_list_widgets","List desktop clock calendar and plugin instances.",true,new string[0]),
        Definition("qidesk_add_widget","Add an instance of an installed plugin, including clock or calendar.",false,new[]{"pluginId"},"pluginId")}.Concat(AiSettings.Tools()).ToArray();}
}
}
